fn max_attempts_bounds_total_calls_including_first() {
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config(3, 1, 100), &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("blip".into()))
    });
    assert_eq!(result, Err(RetryError::Transient("blip".into())));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![1, 2]);
}

