    assert_eq!(result, Err(RetryError::Transient("blip".into())));
    assert_eq!(calls, 6);
    assert_eq!(sleeper.sleeps, vec![100, 200, 300, 300, 300]);
}

#[test]
fn huge_retry_index_does_not_overflow_delay() {
    let config = config(10, 1, 1000);
    assert_eq!(config.delay_ms(10_000), 1000);
